import { addDays, daysBetween } from '../helpers/dates.js';
import { listOverdueLoans } from '../reports/overdue.js';
import { composeNotice } from './compose.js';

/** Loans due within this many days get a reminder in the morning run. */
const DUE_SOON_DAYS = 2;

/** Returns the reminders of the morning run for loans that fall due within two days of today. */
export function dueSoonNotices(store, today) {
  const until = addDays(today, DUE_SOON_DAYS);
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn >= today && loan.dueOn <= until)
    .map((loan) => noticeFor(store, 'dueSoon', loan));
}

/** Returns the notices of the morning run for loans that are overdue today. */
export function overdueNotices(store, today) {
  return listOverdueLoans(store, today).map((loan) => {
    const days = daysBetween(loan.dueOn, today);
    return noticeFor(store, 'overdue', loan, { daysLate: `${days} ${days === 1 ? 'day' : 'days'}` });
  });
}

function noticeFor(store, kind, loan, extraValues = {}) {
  const member = store.getMember(loan.memberId);
  const item = store.getItem(loan.itemId);
  return composeNotice(kind, {
    member,
    values: { title: item.title, dueOn: loan.dueOn, ...extraValues },
  });
}
import { branchById } from '../config/branches.js';
import { composeNotice } from '../notices/compose.js';
import { pickupDeadline } from './pickup.js';

/** Returns the notice that tells a member their hold is ready to collect. */
export function holdReadyNotice(store, hold) {
  const member = store.getMember(hold.memberId);
  const item = store.getItem(hold.itemId);
  return composeNotice('holdReady', {
    member,
    values: {
      title: item.title,
      branch: branchById(hold.pickupBranchId).name,
      deadline: pickupDeadline(hold),
    },
  });
}
/** Lower-cases text and turns every run of punctuation and spaces into one space, for matching. */
export function normaliseText(text) {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

/** Replaces each {name} in a template by the value of that name; unknown names stay as they are. */
export function fillTemplate(template, values) {
  return template.replace(/\{(\w+)\}/g, (placeholder, name) =>
    name in values ? String(values[name]) : placeholder,
  );
}
